const obsIds = new Set($('Get Observations').all().map(i => i.json.id));
const appendix_items = $input.all().map(i => i.json).filter(a => obsIds.has(a.observation_id));
return [{ json: { appendix_items } }];

// v0.2: root causes are now their own table (observation_root_cause), plural per observation,
// each tagged People/Process/Technology with its own explanation. Fetches all rows (Supabase's
// filter condition set has no 'in' operator, same constraint hit elsewhere in this build) and
// keeps only causes belonging to observations actually in this engagement, grouped by observation_id
// so Build Render Payload can attach each observation's cause list directly.
const obsIds = new Set($('Get Observations').all().map(i => i.json.id));
const rows = $input.all().map(i => i.json).filter(rc => obsIds.has(rc.observation_id));
const grouped = {};
for (const rc of rows) {
  if (!grouped[rc.observation_id]) grouped[rc.observation_id] = [];
  grouped[rc.observation_id].push({
    category_people: !!rc.category_people,
    category_process: !!rc.category_process,
    category_technology: !!rc.category_technology,
    explanation: rc.explanation,
    flagged: !!rc.flagged
  });
}
return [{ json: { root_causes_by_observation: grouped } }];

const merged = $input.first().json;
const front_matter = typeof merged.front_matter === 'string' ? JSON.parse(merged.front_matter) : merged.front_matter;
const rootCausesByObs = merged.root_causes_by_observation || {};
const observations = (merged.observations || []).map(o => ({
  ...o,
  root_causes: rootCausesByObs[o.id] || []
}));
return [{ json: {
  engagement_id: merged.id,
  front_matter,
  observations,
  appendix_items: merged.appendix_items || []
} }];

// Lightweight real check (full GR-02 structural diff vs template still to be built):
// confirm the render service actually returned a non-empty document.
const item = $input.first();
const binary = item.binary?.data;
if (!binary || !binary.fileSize || Number(binary.fileSize) === 0) {
  throw new Error('Render service returned an empty or missing document.');
}
return [item];

// Derived sections, rebuilt fresh on every generation (content rule; FR-04/FR-13):
// - Table of Contents with correct page numbers
// - List of Audit Issues: number, risk letter/colour, hyperlinked title, page; owner/target date left blank in draft
// - Audit Issues Dashboard: business areas pre-filled, counts left blank for the auditor
// area_for_improvement observations are EXCLUDED from both the dashboard counts and the issue list (FR-26).
const obs = $input.all().map(i => i.json);
const listable = obs.filter(o => o.risk_rating !== 'area_for_improvement');
const listOfIssues = listable.map((o, idx) => ({
  no: idx + 1, risk_letter: o.risk_rating, title: o.title, hyperlink_target: o.id, page: null, owner: null, target_date: null
}));
return [{ json: { list_of_audit_issues: listOfIssues, observation_count: obs.length } }];

// Placeholder: assign a stable bookmark/content-control id per rendered observation paragraph.
for (const item of $input.all()) {
  item.json.paragraph_id = item.json.id;
}
return $input.all();
